mapper.select:
SELECT /* kr.or.kids.domain.cm.community.qna.mapper.selectQnaList */ A.qstn_sn AS qstnSn , A.pst_ttl AS pstTtl , A.qstnr_nm AS qstnrNm , A.rls_yn AS rlsYn , A.pst_cn AS pstCn , A.pst_inq_cnt AS pstInqCnt , A.atch_file_id AS atchFileId , A.thmb_id AS thmbId , A.del_yn AS delYn , A.rgtr_id AS rgtrId , TO_CHAR(A.reg_dt, 'YYYY-MM-DD') AS regDt , A.mdfr_id AS mdfrId , TO_CHAR(A.mdfcn_dt, 'YYYY-MM-DD') AS mdfcnDt , A.qstn_prgrs_stts_cd AS qstnPrgrsSttsCd , CASE WHEN EXISTS ( SELECT 1 FROM kids_own.tb_cm_m_file_uld U INNER JOIN kids_own.tb_ca_e_file_trsm F ON U.atch_file_id = F.atch_file_group_id WHERE U.pst_sn = A.qstn_sn AND U.del_yn = 'N' AND U.uld_task_se_cd = '06' AND U.file_se_cd = '10' ) THEN 'Y' ELSE 'N' END AS hasFile FROM kids_own.tb_cm_m_qna A WHERE 1=1 AND A.del_yn = 'N' AND A.bbs_id = #{bbsId}
AND A.rgtr_id = #{loginId}
AND A.qstn_prgrs_stts_cd = #{qstnPrgrsSttsCd}
AND A.pst_ttl LIKE '%' || #{searchKeyword} || '%'
AND A.pst_cn LIKE '%' || #{searchKeyword} || '%'
AND A.rgtr_id IN ( SELECT m.mbr_no FROM kids_own.tb_pp_m_mbr_info m WHERE m.encpt_mbr_flnm = #{encryptedWriterKeyword} )
AND A.qstnr_nm LIKE '%' || #{searchKeyword} || '%'
AND EXISTS ( SELECT 1 FROM kids_own.tb_pp_m_exprt_info ei JOIN kids_own.tb_pp_m_inst i ON i.brno = ei.brno WHERE ei.mbr_no = A.rgtr_id AND i.inst_nm LIKE '%' || #{searchKeyword} || '%' )
ORDER BY A.qstn_sn DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

SELECT /* kr.or.kids.domain.cm.community.qna.mapper.selectQnaListCount */ COUNT(*) FROM kids_own.tb_cm_m_qna A WHERE 1=1 AND A.del_yn = 'N' AND A.bbs_id = #{bbsId}
AND A.rgtr_id = #{loginId}
AND A.qstn_prgrs_stts_cd = #{qstnPrgrsSttsCd}
AND A.pst_ttl LIKE '%' || #{searchKeyword} || '%'
AND A.pst_cn LIKE '%' || #{searchKeyword} || '%'
AND A.rgtr_id IN ( SELECT m.mbr_no FROM kids_own.tb_pp_m_mbr_info m WHERE m.encpt_mbr_flnm = #{encryptedWriterKeyword} )
AND A.qstnr_nm LIKE '%' || #{searchKeyword} || '%'
AND EXISTS ( SELECT 1 FROM kids_own.tb_pp_m_exprt_info ei JOIN kids_own.tb_pp_m_inst i ON i.brno = ei.brno WHERE ei.mbr_no = A.rgtr_id AND i.inst_nm LIKE '%' || #{searchKeyword} || '%' )

mapper.update:
/* kr.or.kids.domain.cm.community.qna.mapper.updateQnaAnswer */
UPDATE kids_own.tb_cm_m_qna_ans


        ans_cn = #{ansCn},



        mdfr_id = #{mdfrId},


    mdfcn_dt = NOW()

WHERE ans_sn = #{ansSn}

/* kr.or.kids.domain.cm.community.qna.mapper.updateQnaStatusAnswered */
UPDATE kids_own.tb_cm_m_qna
   SET qstn_prgrs_stts_cd = '02'
     , mdfcn_dt = NOW()
 WHERE qstn_sn = #{qstnSn}

/* kr.or.kids.domain.cm.community.qna.mapper.updateQnaStatusWaiting */
UPDATE kids_own.tb_cm_m_qna
   SET qstn_prgrs_stts_cd = '01'
     , mdfcn_dt = NOW()
 WHERE qstn_sn = #{qstnSn}

/* kr.or.kids.domain.cm.community.qna.mapper.deleteQna */
UPDATE kids_own.tb_cm_m_qna
   SET del_yn = 'Y'
     , mdfcn_dt = NOW()
 WHERE qstn_sn = #{qstnSn}

/* kr.or.kids.domain.cm.community.qna.mapper.deleteQnaAnswer */
UPDATE kids_own.tb_cm_m_qna_ans
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
 WHERE ans_sn = #{ansSn}

/* kr.or.kids.domain.cm.community.qna.mapper.deleteAnswerByQstnSn */
UPDATE kids_own.tb_cm_m_qna_ans
   SET use_yn = 'N'
     , mdfcn_dt = NOW()
 WHERE qstn_sn = #{qstnSn}

/* kr.or.kids.domain.cm.community.qna.mapper.updateQnaViewCount */
UPDATE kids_own.tb_cm_m_qna
   SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
     , mdfcn_dt = NOW()
 WHERE qstn_sn = #{qstnSn}
   AND del_yn = 'N'
